import{_ as s,o as e,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"网络","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/network.md","filePath":"zh/manual/network.md"}'),i={name:"zh/manual/network.md"};function p(l,a,o,c,h,d){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h1><p>网络操作面位于 <code>net-tool</code>（向导）及其之下的经典命令背后。</p><h2 id="地址配置" tabindex="-1">地址配置 <a class="header-anchor" href="#地址配置" aria-label="Permalink to &quot;地址配置&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; net-tool               -&gt; &quot;obtain an address via DHCP&quot;</span></span>
<span class="line"><span>ush&gt; dhcp                   (the classic form - same call)</span></span>
<span class="line"><span>ush&gt; ip                     (show IP / mask / gateway)</span></span></code></pre></div><p>通过向导做静态配置时，地址、掩码和网关逐字段采集，因此位置参数行永远不会以错误的顺序拼接。经典形式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; ip 10.0.2.15 255.255.255.0 10.0.2.2</span></span></code></pre></div><h2 id="域名解析" tabindex="-1">域名解析 <a class="header-anchor" href="#域名解析" aria-label="Permalink to &quot;域名解析&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dns example.com              A record (+CNAME when present)</span></span>
<span class="line"><span>ush&gt; dns example.com aaaa         AAAA / cname / mx / txt / ns / srv</span></span>
<span class="line"><span>ush&gt; dnstest                      every record type against the resolver</span></span></code></pre></div><p>DNS 经过所配置的解析器；在 QEMU 用户态网络下，slirp 协议栈会把请求转发给真实的上游。</p><h2 id="连通性测试" tabindex="-1">连通性测试 <a class="header-anchor" href="#连通性测试" aria-label="Permalink to &quot;连通性测试&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; net-tool               -&gt; ping / wget / ssh / dnstest submenu</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2</span></span>
<span class="line"><span>ush&gt; wget example.com 80 /</span></span>
<span class="line"><span>ush&gt; wget https.example 443 /           (TLS is built in)</span></span></code></pre></div><p><code>ping</code> 和 <code>wget</code> 走内核的 NETCMD 桥——正是历史应用所用的那个系统调用。</p><h2 id="wifi-与蓝牙" tabindex="-1">WiFi 与蓝牙 <a class="header-anchor" href="#wifi-与蓝牙" aria-label="Permalink to &quot;WiFi 与蓝牙&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; net-tool               -&gt; WiFi manager: status / scan / test / sdio</span></span>
<span class="line"><span>ush&gt; wifi scan              (beacon-derived network list)</span></span>
<span class="line"><span>ush&gt; net-tool               -&gt; Bluetooth: status / usb / uart / test</span></span>
<span class="line"><span>ush&gt; bt                     (transport + controller status)</span></span></code></pre></div><p>无线层按家族（ath、brcm、iwlwifi、rtlwifi）如实报告状态：已注册、扫描中、已连接——没有相应硬件的机器会直说，而不是假装。</p><h2 id="防火墙" tabindex="-1">防火墙 <a class="header-anchor" href="#防火墙" aria-label="Permalink to &quot;防火墙&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; firewall               (list rules + policies)</span></span>
<span class="line"><span>ush&gt; firewall add ...       (rule management - see the commands page)</span></span>
<span class="line"><span>ush&gt; firewall ct            (the connection-tracking table)</span></span></code></pre></div><h2 id="路由与-arp" tabindex="-1">路由与 ARP <a class="header-anchor" href="#路由与-arp" aria-label="Permalink to &quot;路由与 ARP&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; route                  (the full routing table)</span></span>
<span class="line"><span>ush&gt; route add 10.0.0.0 255.0.0.0 10.0.2.2</span></span>
<span class="line"><span>ush&gt; arp                    (the ARP cache)</span></span></code></pre></div><h2 id="ssh-进出" tabindex="-1">SSH 进出 <a class="header-anchor" href="#ssh-进出" aria-label="Permalink to &quot;SSH 进出&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; sshd                   (serve the shell - port/user/pass optional)</span></span>
<span class="line"><span>ush&gt; ssh 10.0.2.2           (connect out; credentials as arguments)</span></span></code></pre></div><p>SSH 协议栈运行真实的 KEX/加密协商流程；主机密钥可预置在 /etc 卷上以支持无人值守启动。在 QEMU 下，用 <code>-netdev user,hostfwd=tcp::2223-:22</code> 转发端口，再从宿主机连接。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><ul><li><strong>DHCP 之后没有 IP</strong>——检查网卡型号（<code>hwinfo</code> -&gt; PCI）以及 <code>-netdev user</code> 是否存在；e1000 系列测试最充分。</li><li><strong>DNS 超时</strong>——slirp 的 DNS 转发只在用户态网络下有效；在桥接 tap 上需要真实的解析器。</li><li><strong>首次 SSH 连接卡住</strong>——DHCP 之后 ARP 缓存还是冷的；先跑一条客户端方向的命令（<code>ping</code> 对端）预热，再连接。</li></ul><p>更多内容见 <a href="./../troubleshooting/network-issues.html">../troubleshooting/network-issues.md</a>。</p>`,25)])])}const g=s(i,[["render",p]]);export{u as __pageData,g as default};
